mapper.select:
SELECT
t.id,
t.name,
t.gh,
t.qybh,
t.account_status AS accountStatus
FROM ve_yg_4849 t
WHERE t.qybh = #{dto.qybh}

    AND t.gh = #{dto.gh}



    AND t.name LIKE #{nameLike}


    AND t.account_status = #{dto.accountStatus}

ORDER BY t.gh

SELECT yg.id, yg.gh, yg.name, yg.english_surname AS englishSurname, yg.english_name AS englishName, yg.phone, yg.email, yg.gender, yg.birthday, yg.account_status AS accountStatus, rz.dept_id AS deptId, bm.bh, bm.short_name AS shortName, rz.position_code AS positionCode, rz.position_name AS positionName, rz.job_level AS jobLevel, rz.supervisor_id AS supervisorId, sj.name AS supervisorName FROM ve_yg_4849 yg LEFT JOIN ve_ygrz_4849 rz ON yg.id = rz.ygid AND yg.qybh = rz.qybh AND rz.status = '1' LEFT JOIN ve_bm_4849 bm ON rz.dept_id = bm.dept_id AND rz.qybh = bm.qybh LEFT JOIN ve_yg_4849 sj ON rz.supervisor_id = sj.id AND rz.qybh = sj.qybh WHERE yg.qybh = #{dto.qybh}
AND yg.gh LIKE CONCAT('%', #{dto.gh}, '%')
AND yg.name LIKE #{nameLike}
AND rz.dept_id = #{dto.deptId}
AND rz.position_code = #{dto.positionCode}
AND yg.gender = #{dto.gender}
ORDER BY yg.gh

SELECT yg.id, yg.gh, yg.name, yg.phone, yg.email, yg.gender, rz.position_code AS positionCode, rz.position_name AS positionName, rz.job_level AS jobLevel, rz.dept_id AS deptId, bm.short_name AS shortName FROM ve_yg_4849 yg INNER JOIN ve_ygrz_4849 rz ON yg.id = rz.ygid AND yg.qybh = rz.qybh AND rz.status = '1' INNER JOIN ve_bm_4849 bm ON rz.dept_id = bm.dept_id AND rz.qybh = bm.qybh WHERE yg.qybh = #{dto.qybh} AND bm.dept_id = #{dto.deptId}
AND yg.name LIKE #{nameLike}
ORDER BY yg.gh
